using InsuranceAutomation.Core.SelfHealing;
using InsuranceAutomation.Core; using Reqnroll;
namespace InsuranceAutomation.CLDC.Hooks;
[Binding] public sealed class TestHooks { readonly ScenarioContext _scenario; readonly FeatureContext _feature; readonly FrameworkSettings _settings=new(); public TestHooks(ScenarioContext scenario, FeatureContext feature){_scenario=scenario;_feature=feature;} [BeforeScenario(Order=-100)] public async Task StartAsync(){if(_settings.KillStaleBrowsers) Kill();var browser=new BrowserSession();await browser.StartAsync(_settings);var data=new ScenarioData();var ui=new PageUiActions(browser);_scenario.Set(browser);_scenario.Set(data);_scenario.Set(ui);_scenario.Set(new ManualTrace());} [BeforeStep] public void BeforeStep(){var data=_scenario.Get<ScenarioData>();ExecutionIntentContext.Set(_feature.FeatureInfo.Title,_scenario.ScenarioInfo.Title,_scenario.StepContext.StepInfo.Text);_scenario.Get<ManualTrace>().Add(_scenario.StepContext.StepInfo.Text,"Started",string.Join("; ",data.Snapshot().Select(x=>$"{x.Key}={x.Value}")));} [AfterStep] public async Task AfterStep(){var data=_scenario.Get<ScenarioData>();var trace=_scenario.Get<ManualTrace>();var failed=_scenario.TestError!=null;trace.Add(_scenario.StepContext.StepInfo.Text,failed?"Failed":"Passed",string.Join("; ",data.Snapshot().Select(x=>$"{x.Key}={x.Value}")));if(failed){Directory.CreateDirectory("Artifacts/Screenshots");await _scenario.Get<BrowserSession>().Page.ScreenshotAsync(new(){Path=$"Artifacts/Screenshots/{Safe(_scenario.ScenarioInfo.Title)}.png",FullPage=true});}} [AfterScenario(Order=100)] public async Task EndAsync(){var trace=_scenario.Get<ManualTrace>();Directory.CreateDirectory("Artifacts/Reports");trace.Write($"Artifacts/Reports/{Safe(_scenario.ScenarioInfo.Title)}.html",_scenario.ScenarioInfo.Title);await _scenario.Get<PageUiActions>().DisposeAsync();ExecutionIntentContext.Clear();await _scenario.Get<BrowserSession>().StopAsync($"Artifacts/Traces/{Safe(_scenario.ScenarioInfo.Title)}.zip",_settings.Trace);} static string Safe(string s)=>string.Concat(s.Select(c=>char.IsLetterOrDigit(c)?c:'_')); static void Kill(){if(!OperatingSystem.IsWindows())return;foreach(var p in new[]{"msedge","chrome","iexplore","firefox"})try{foreach(var x in System.Diagnostics.Process.GetProcessesByName(p))x.Kill(true);}catch{}} }